static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        String timeStr = String.format("%08d", timeBucket);
        int day = Integer.parseInt(timeStr.substring(4));
        int newDay = (day - (day % dayStep)) % 365;
        if (day - newDay < 10) {
            newDay += dayStep;
        } else if (day - newDay >= 364) {
            newDay -= dayStep;
        }
        return Long.parseLong("2000" + timeStr.substring(2, 4) + String.format("%02d", newDay));
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid timeBucket or dayStep input: " + timeBucket + ", " + dayStep, e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + index);
    }
    if (len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Length out of bounds: " + len);
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else if (c <= 0x10FFFF) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-16 character: " + c);
        }
    }
    return size;
}

