final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }

    if (charBuffer == null) {
        throw new NullPointerException("charBuffer cannot be null");
    }

    int utfLength = classFileBuffer[constantPoolEntryIndex] & 0xFF;
    int offset = constantPoolEntryIndex + 1;

    if (offset + utfLength > classFileBuffer.length) {
        throw new ArrayIndexOutOfBoundsException("Buffer overflow");
    }

    if (charBuffer.length < utfLength) {
        throw new IllegalArgumentException("charBuffer is too small to hold the string");
    }

    for (int i = 0; i < utfLength; i++) {
        charBuffer[i] = (char) (classFileBuffer[offset] & 0xFF);
        offset++;
    }

    return new String(charBuffer, 0, utfLength);
}

