private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;
    long currentSum = bounds.stream().mapToLong(Long::intValue).sum();

    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum -= bounds.get(i);
        suffixSumList.add(0, (int) currentSum);
        totalSum += bounds.get(i);
    }

    suffixSumList.add(0, (int) totalSum);

    return Pair.with(suffixSumList, totalSum);
}

