    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range specified");
    }

    int left = from;
    int right = to;
    while (left < right) {
        // Swap elements
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        left++;
        right--;
    }
}

