            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                descriptor = descriptor.substring(1);
                break;
            case '[': // array
                descriptor = descriptor.substring(1);
                break;
            case 'L': { // object
                int semiColonIndex = descriptor.indexOf(';', 1);
                if (semiColonIndex == -1) {
                    throw new IllegalArgumentException("Invalid descriptor format);
                }
                descriptor = descriptor.substring(semiColonIndex + 1);
                break;
            }
            case '(': { // method
                int closeParenthesisIndex = descriptor.indexOf(')', 1);
                if (closeParenthesisIndex == -1) {
                    throw new IllegalArgumentException("Invalid descriptor format");
                }
                descriptor = descriptor.substring(closeParenthesisIndex + 1);
                break;
            }
